// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration
const morgan = require('morgan'); // Logging
const validator = require('validator'); // Input validation

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet - Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS - Configure allowed origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true
};
app.use(cors(corsOptions));

// 3. Rate limiting - Prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests, please try again later.',
});

// 4. Body parsing with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb'
}));

// 5. Request logging (use 'combined' for production)
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// 6. Disable X-Powered-By header
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Validate user ID parameter
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID is required'
    });
  }

  // Check if ID is a valid positive integer
  if (!validator.isInt(id, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID must be a positive integer'
    });
  }

  // Store sanitized ID
  req.sanitizedId = parseInt(id, 10);
  next();
};

// Validate query parameters
const validateQueryParams = (req, res, next) => {
  const { page, limit, search } = req.query;

  // Validate pagination parameters
  if (page && !validator.isInt(page, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Page must be a positive integer'
    });
  }

  if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Limit must be between 1 and 100'
    });
  }

  // Sanitize search parameter to prevent XSS
  if (search) {
    const sanitizedSearch = validator.escape(search);
    req.sanitizedQuery = {
      ...req.query,
      search: sanitizedSearch
    };
  }

  next();
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    // Log error but don't expose details
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Health check failed'
    });
  }
});

// Get all users with validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    // In production, this would query a database
    // with proper parameterized queries to prevent SQL injection
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if provided
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to fetch users'
    });
  }
});

// Get single user by ID
app.get('/users/:id', strictLimiter, validateUserId, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === req.sanitizedId);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found'
      });
    }

    res.json({ data: user });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to fetch user'
    });
  }
});

// Create user endpoint (example with POST validation)
app.post('/users', strictLimiter, (req, res) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Name and email are required'
      });
    }

    // Validate name (alphanumeric with spaces, 2-50 chars)
    if (!validator.isLength(name, { min: 2, max: 50 })) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Name must be between 2 and 50 characters'
      });
    }

    // Validate email format
    if (!validator.isEmail(email)) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Invalid email format'
      });
    }

    // Sanitize inputs
    const sanitizedName = validator.escape(name.trim());
    const sanitizedEmail = validator.normalizeEmail(email.trim());

    // In production, save to database with parameterized queries
    const newUser = {
      id: 3, // Would be generated by database
      name: sanitizedName,
      email: sanitizedEmail
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to create user'
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler - Must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found'
  });
});

// Global error handler - Must be last
app.use((err, req, res, next) => {
  // Log error details for debugging (use proper logging service in production)
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't expose internal error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred'
    : err.message;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : 'Error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// SERVER INITIALIZATION
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

