// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const validator = require('validator');

const app = express();

// Security Middleware
// ===================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS - Configure allowed origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
};
app.use(cors(corsOptions));

// 3. Rate Limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// More strict rate limiting for specific endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Rate limit exceeded for this endpoint.',
});

// 4. Body Parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Disable X-Powered-By header
app.disable('x-powered-by');

// Utility Functions
// =================

/**
 * Sanitize and validate query parameters
 */
const sanitizeQueryParams = (params) => {
  const sanitized = {};
  for (const [key, value] of Object.entries(params)) {
    if (typeof value === 'string') {
      // Remove any potential script tags or harmful characters
      sanitized[key] = validator.escape(value.trim());
    } else {
      sanitized[key] = value;
    }
  }
  return sanitized;
};

/**
 * Validate user ID parameter
 */
const validateUserId = (id) => {
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId < 1 || numId > 1000000) {
    return { valid: false, error: 'Invalid user ID' };
  }
  return { valid: true, value: numId };
};

/**
 * Mask sensitive data (email addresses)
 */
const maskEmail = (email) => {
  if (!email || typeof email !== 'string') return '';
  const [localPart, domain] = email.split('@');
  if (!domain) return '***';
  const maskedLocal = localPart.length > 2 
    ? localPart[0] + '***' + localPart[localPart.length - 1]
    : '***';
  return `${maskedLocal}@${domain}`;
};

// Logging Middleware
// ==================
const requestLogger = (req, res, next) => {
  const start = Date.now();

  // Log response when finished
  res.on('finish', () => {
    const duration = Date.now() - start;
    const logEntry = {
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    };

    // In production, use proper logging library (winston, pino, etc.)
    console.log(JSON.stringify(logEntry));

    // Alert on suspicious activity
    if (res.statusCode >= 400) {
      console.warn('⚠️ Error response:', logEntry);
    }
  });

  next();
};

app.use(requestLogger);

// Routes
// ======

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Service unavailable' 
    });
  }
});

/**
 * Get all users endpoint
 * In production: Add authentication, pagination, and database integration
 */
app.get('/users', strictLimiter, (req, res, next) => {
  try {
    // Sanitize query parameters
    const sanitizedParams = sanitizeQueryParams(req.query);

    // Validate pagination parameters if present
    let page = 1;
    let limit = 10;

    if (sanitizedParams.page) {
      page = parseInt(sanitizedParams.page, 10);
      if (isNaN(page) || page < 1) {
        return res.status(400).json({ 
          error: 'Invalid page parameter',
          message: 'Page must be a positive integer'
        });
      }
    }

    if (sanitizedParams.limit) {
      limit = parseInt(sanitizedParams.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({ 
          error: 'Invalid limit parameter',
          message: 'Limit must be between 1 and 100'
        });
      }
    }

    // Mock data - in production, fetch from database with proper access control
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'example.com' },
    ];

    // Mask sensitive data before sending
    // In production: Only return email if user is authenticated and authorized
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: validator.escape(user.name),
      email: maskEmail(user.email) // Mask email for privacy
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

/**
 * Get user by ID endpoint
 */
app.get('/users/:id', strictLimiter, (req, res, next) => {
  try {
    // Validate user ID
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({ 
        error: 'Validation error',
        message: validation.error 
      });
    }

    const userId = validation.value;

    // Mock data - in production, fetch from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not found',
        message: 'User not found' 
      });
    }

    // Sanitize and mask sensitive data
    const sanitizedUser = {
      id: user.id,
      name: validator.escape(user.name),
      email: maskEmail(user.email)
    };

    res.json({ data: sanitizedUser });
  } catch (error) {
    next(error);
  }
});

// 404 Handler
// ===========
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: 'The requested resource does not exist',
    path: req.path
  });
});

// Global Error Handler
// ====================
app.use((err, req, res, next) => {
  // Log the full error for debugging
  console.error('Error occurred:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Don't expose internal error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An internal server error occurred'
    : err.message;

  res.status(statusCode).json({
    error: 'Internal server error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Graceful Shutdown
// =================
const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, log to external service and gracefully shutdown
  server.close(() => {
    process.exit(1);
  });
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, log to external service
});

module.exports = app;

// Security Test Suite for app.js
// Run with: npm test

const request = require('supertest');

// Import both versions for comparison
const originalApp = require('./app');
const improvedApp = require('./app-improved');

describe('Security Tests - Original App', () => {
  describe('XSS Vulnerability Tests', () => {
    it('should be vulnerable to XSS in query parameters', async () => {
      const response = await request(originalApp)
        .get('/users?search=<script>alert("xss")</script>');
      // Original app doesn't sanitize - vulnerability exists
      expect(response.status).toBe(200);
    });
  });

  describe('DoS Vulnerability Tests', () => {
    it('should have no rate limiting (DoS vulnerable)', async () => {
      // Send 200 rapid requests - should all succeed
      const requests = Array(200).fill().map(() => 
        request(originalApp).get('/health')
      );
      const responses = await Promise.all(requests);
      const successCount = responses.filter(r => r.status === 200).length;
      expect(successCount).toBe(200); // All succeed - no rate limiting
    });
  });

  describe('Error Handling Tests', () => {
