// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const morgan = require('morgan'); // Logging
const validator = require('validator'); // Input validation
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers - Protect against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Request body parsing with size limits to prevent payload attacks
app.use(express.json({ 
  limit: '10kb',
  strict: true 
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 3. Rate Limiting - Prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Logging - Track requests for security monitoring
app.use(morgan('combined'));

// 5. Disable X-Powered-By header to hide Express
app.disable('x-powered-by');

// ============================================
// CONFIGURATION
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'User ID is required' 
    });
  }

  if (!validator.isInt(id, { min: 1, max: 999999 })) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid user ID format' 
    });
  }

  next();
};

const validateQueryParams = (req, res, next) => {
  const { limit, offset, search } = req.query;

  // Validate limit parameter
  if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid limit parameter. Must be between 1 and 100' 
    });
  }

  // Validate offset parameter
  if (offset && !validator.isInt(offset, { min: 0 })) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid offset parameter. Must be a non-negative integer' 
    });
  }

  // Validate and sanitize search parameter
  if (search) {
    // Check for potential SQL injection or XSS patterns
    if (search.length > 100) {
      return res.status(400).json({ 
        error: 'Bad Request',
        message: 'Search query too long' 
      });
    }

    // Sanitize the search string
    req.query.search = validator.escape(search);
  }

  next();
};

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Async error wrapper to catch errors in async route handlers
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// MOCK DATABASE (Replace with real database)
// ============================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: NODE_ENV
  });
});

// Get all users with pagination and search
app.get('/users', validateQueryParams, asyncHandler(async (req, res) => {
  try {
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const search = req.query.search;

    let filteredUsers = [...users];

    // Apply search filter if provided
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.status(200).json({
      success: true,
      data: paginatedUsers,
      metadata: {
        total: filteredUsers.length,
        limit,
        offset,
        returned: paginatedUsers.length
      }
    });
  } catch (error) {
    throw new AppError('Error retrieving users', 500);
  }
}));

// Get single user by ID
app.get('/users/:id', validateUserId, asyncHandler(async (req, res, next) => {
  const userId = parseInt(req.params.id);

  const user = users.find(u => u.id === userId);

  if (!user) {
    return next(new AppError('User not found', 404));
  }

  res.status(200).json({
    success: true,
    data: user
  });
}));

// ============================================
// 404 HANDLER
// ============================================

app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`,
    path: req.originalUrl
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error for debugging (use proper logging service in production)
  console.error('ERROR 💥:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Development error response (detailed)
  if (NODE_ENV === 'development') {
    res.status(err.statusCode).json({
      error: err.status,
      message: err.message,
      stack: err.stack,
      details: err
    });
  } 
  // Production error response (sanitized)
  else {
    // Don't leak error details in production
    if (err.isOperational) {
      res.status(err.statusCode).json({
        error: err.status,
        message: err.message
      });
    } else {
      // Programming or unknown errors: don't leak details
      res.status(500).json({
        error: 'error',
        message: 'Something went wrong. Please try again later.'
      });
    }
  }
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

let server;

const startServer = () => {
  server = app.listen(PORT, () => {
    console.log(`🚀 Server running on port ${PORT} in ${NODE_ENV} mode`);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (err) => {
    console.error('UNHANDLED REJECTION! 💥 Shutting down...');
    console.error(err.name, err.message);
    server.close(() => {
      process.exit(1);
    });
  });

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
    console.error(err.name, err.message);
    process.exit(1);
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('👋 SIGTERM RECEIVED. Shutting down gracefully');
    server.close(() => {
      console.log('💥 Process terminated!');
    });
  });
};

// Only start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = app;

