## Additional Best Practices

### 1. **Use HTTPS Only**
```javascript
// Redirect HTTP to HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

### 2. **Implement Authentication/Authorization**
```javascript
const jwt = require('jsonwebtoken');

// Middleware to verify JWT
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(401).json({ error: 'Invalid token' });
  }
};

// Protected route
app.get('/users', authenticate, (req, res) => {
  // Only authenticated users can access
});
```

### 3. **SQL Injection Prevention**
```javascript
// BAD - String concatenation
const query = `SELECT * FROM users WHERE id = ${req.params.id}`;

// GOOD - Parameterized queries
const query = 'SELECT * FROM users WHERE id = $1';
await db.query(query, [req.params.id]);
```

### 4. **Sanitize User Output**
```javascript
const xss = require('xss');

// Sanitize before storing
const sanitizedName = xss(req.body.name);

// Or use express-validator's escape()
body('name').trim().escape()
```

### 5. **Implement Request Timeouts**
```javascript
const timeout = require('connect-timeout');

app.use(timeout('5s')); // 5 second timeout
app.use((req, res, next) => {
  if (!req.timedout) next();
});
```

### 6. **Content Security Policy**
```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"]
  }
}));
```

### 7. **Secure Session Management** (if using sessions)
```javascript
const session = require('express-session');

app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: true, // HTTPS only
    httpOnly: true, // Not accessible via JavaScript
    maxAge: 3600000, // 1 hour
    sameSite: 'strict' // CSRF protection
  }
}));
```

### 8. **Database Security**
- Use connection pooling
- Implement least privilege access
- Use parameterized queries
- Encrypt sensitive data at rest
- Regular backups

