// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const morgan = require('morgan'); // Request logging

const app = express();

// ===========================
// SECURITY MIDDLEWARE
// ===========================

// 1. Security headers with helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. Rate limiting to prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests to this endpoint, please try again later.',
});

// 4. Request logging for security auditing
app.use(morgan('combined'));

// 5. Disable X-Powered-By header to avoid revealing technology stack
app.disable('x-powered-by');

// ===========================
// INPUT VALIDATION HELPERS
// ===========================

/**
 * Validates and sanitizes query parameters
 * @param {Object} query - Express query object
 * @param {Object} schema - Validation schema
 * @returns {Object} - { isValid: boolean, errors: array, sanitized: object }
 */
function validateQuery(query, schema) {
  const errors = [];
  const sanitized = {};

  for (const [key, rules] of Object.entries(schema)) {
    const value = query[key];

    // Check if required
    if (rules.required && !value) {
      errors.push(`${key} is required`);
      continue;
    }

    // Skip validation if optional and not provided
    if (!value && !rules.required) {
      continue;
    }

    // Type validation
    if (rules.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) {
        errors.push(`${key} must be a valid number`);
        continue;
      }
      if (rules.min !== undefined && num < rules.min) {
        errors.push(`${key} must be at least ${rules.min}`);
        continue;
      }
      if (rules.max !== undefined && num > rules.max) {
        errors.push(`${key} must be at most ${rules.max}`);
        continue;
      }
      sanitized[key] = num;
    } else if (rules.type === 'string') {
      // Sanitize string input
      let sanitizedValue = validator.escape(String(value).trim());

      if (rules.maxLength && sanitizedValue.length > rules.maxLength) {
        errors.push(`${key} must be at most ${rules.maxLength} characters`);
        continue;
      }
      if (rules.pattern && !rules.pattern.test(sanitizedValue)) {
        errors.push(`${key} has invalid format`);
        continue;
      }
      sanitized[key] = sanitizedValue;
    } else if (rules.type === 'email') {
      if (!validator.isEmail(value)) {
        errors.push(`${key} must be a valid email address`);
        continue;
      }
      sanitized[key] = validator.normalizeEmail(value);
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
    sanitized
  };
}

// ===========================
// ERROR HANDLING MIDDLEWARE
// ===========================

/**
 * Custom error class for application errors
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Async error wrapper to catch async errors
 */
const catchAsync = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ===========================
// ROUTES
// ===========================

app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    // Even simple endpoints should have error handling
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

app.get('/users', strictLimiter, catchAsync(async (req, res, next) => {
  // Validate query parameters
  const validation = validateQuery(req.query, {
    page: { 
      type: 'number', 
      required: false, 
      min: 1, 
      max: 1000 
    },
    limit: { 
      type: 'number', 
      required: false, 
      min: 1, 
      max: 100 
    },
    search: { 
      type: 'string', 
      required: false, 
      maxLength: 100 
    }
  });

  if (!validation.isValid) {
    return res.status(400).json({
      status: 'error',
      message: 'Invalid input parameters',
      errors: validation.errors
    });
  }

  const { page = 1, limit = 10, search } = validation.sanitized;

  // Simulate database query with validated inputs
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply search filter if provided
  if (search) {
    users = users.filter(user => 
      user.name.toLowerCase().includes(search.toLowerCase())
    );
  }

  // Apply pagination
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  const paginatedUsers = users.slice(startIndex, endIndex);

  // Return response with metadata
  res.status(200).json({
    status: 'success',
    results: paginatedUsers.length,
    total: users.length,
    page,
    limit,
    data: paginatedUsers
  });
}));

// Add a POST endpoint example with input validation
app.post('/users', strictLimiter, catchAsync(async (req, res, next) => {
  const { name, email } = req.body;

  // Validate required fields
  if (!name || !email) {
    throw new AppError('Name and email are required', 400);
  }

  // Validate name
  if (typeof name !== 'string' || name.trim().length === 0) {
    throw new AppError('Name must be a non-empty string', 400);
  }

  if (name.length > 100) {
    throw new AppError('Name must not exceed 100 characters', 400);
  }

  // Validate email
  if (!validator.isEmail(email)) {
    throw new AppError('Invalid email address', 400);
  }

  // Sanitize inputs
  const sanitizedName = validator.escape(name.trim());
  const sanitizedEmail = validator.normalizeEmail(email);

  // TODO: Add authentication/authorization check here
  // if (!req.user || !req.user.isAdmin) {
  //   throw new AppError('Unauthorized access', 403);
  // }

  // TODO: Save to database with parameterized queries to prevent SQL injection
  const newUser = {
    id: Date.now(), // In production, this would be generated by the database
    name: sanitizedName,
    email: sanitizedEmail
  };

  res.status(201).json({
    status: 'success',
    data: newUser
  });
}));

// ===========================
// 404 HANDLER
// ===========================

app.use((req, res, next) => {
  const error = new AppError(`Cannot find ${req.originalUrl} on this server`, 404);
  next(error);
});

// ===========================
// GLOBAL ERROR HANDLER
// ===========================

app.use((err, req, res, next) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Development error response (detailed)
  if (process.env.NODE_ENV === 'development') {
    res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  } 
  // Production error response (minimal information)
  else {
    // Operational, trusted error: send message to client
    if (err.isOperational) {
      res.status(err.statusCode).json({
        status: err.status,
        message: err.message
      });
    } 
    // Programming or unknown error: don't leak error details
    else {
      console.error('ERROR 💥', err);
      res.status(500).json({
        status: 'error',
        message: 'Something went wrong'
      });
    }
  }
});

// ===========================
// GRACEFUL SHUTDOWN
// ===========================

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

process.on('SIGTERM', () => {
