// Improved application with security best practices
// Implements comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const morgan = require('morgan'); // Logging

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too Many Requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime
    });
  }
});

app.use(limiter);

// Body parser with size limits (prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
} else {
  app.use(morgan('combined'));
}

// Disable X-Powered-By header
app.disable('x-powered-by');

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID is required'
    });
  }

  // Validate ID is a positive integer
  if (!validator.isInt(id, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID must be a positive integer'
    });
  }

  next();
};

const validateQueryParams = (req, res, next) => {
  const { page, limit, search } = req.query;

  // Validate pagination parameters
  if (page && !validator.isInt(String(page), { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Page must be a positive integer'
    });
  }

  if (limit && !validator.isInt(String(limit), { min: 1, max: 100 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Limit must be between 1 and 100'
    });
  }

  // Sanitize search parameter to prevent XSS
  if (search) {
    const sanitized = validator.escape(String(search));
    if (sanitized.length > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Search query too long (max 100 characters)'
      });
    }
    req.query.search = sanitized;
  }

  next();
};

