## ⚠️ Common Pitfalls to Avoid

### ❌ DON'T
```javascript
// Don't trust user input
app.get('/users/:id', (req, res) => {
  const id = req.params.id; // No validation!
  // Use directly in query - DANGEROUS!
});

// Don't leak errors
app.use((err, req, res, next) => {
  res.json({ error: err.stack }); // Exposes internals!
});

// Don't ignore errors
app.get('/users', (req, res) => {
  // No try-catch - will crash on error!
  const users = getUsers();
  res.json(users);
});
```

### ✅ DO
```javascript
// Validate all input
app.get('/users/:id', validateUserId, (req, res, next) => {
  try {
    const id = parseInt(req.params.id); // Already validated
    // Safe to use
  } catch (error) {
    next(error);
  }
});

// Sanitize error messages
app.use((err, req, res, next) => {
  res.json({ 
    error: 'Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message 
  });
});

// Always handle errors
app.get('/users', async (req, res, next) => {
  try {
    const users = await getUsers();
    res.json(users);
  } catch (error) {
    next(error); // Caught by error handler
  }
});
```

