// Improved application with security best practices and error handling

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const cors = require('cors');
const validator = require('validator');

const app = express();

// ===========================================
// SECURITY MIDDLEWARE
// ===========================================

// Set security HTTP headers
app.use(helmet());

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Body parser with size limits to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL query injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Enable CORS with restrictions
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// ===========================================
// CUSTOM VALIDATION MIDDLEWARE
// ===========================================

// Validate user ID parameter
const validateUserId = (req, res, next) => {
  try {
    const { id } = req.params;

    if (!id) {
      return res.status(400).json({
        status: 'error',
        message: 'User ID is required'
      });
    }

    // Ensure ID is a valid integer
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({
        status: 'error',
        message: 'Invalid user ID format'
      });
    }

    req.validatedUserId = userId;
    next();
  } catch (error) {
    next(error);
  }
};

// Validate query parameters
const validateQueryParams = (req, res, next) => {
  try {
    const { limit, page, sort } = req.query;

    // Validate limit
    if (limit !== undefined) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          status: 'error',
          message: 'Limit must be between 1 and 100'
        });
      }
      req.validatedQuery = { ...req.validatedQuery, limit: limitNum };
    }

    // Validate page
    if (page !== undefined) {
      const pageNum = parseInt(page, 10);
      if (isNaN(pageNum) || pageNum < 1) {
        return res.status(400).json({
          status: 'error',
          message: 'Page must be a positive integer'
        });
      }
      req.validatedQuery = { ...req.validatedQuery, page: pageNum };
    }

    // Validate sort (whitelist approach)
    if (sort !== undefined) {
      const allowedSortFields = ['id', 'name', 'email', '-id', '-name', '-email'];
      if (!allowedSortFields.includes(sort)) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid sort field'
        });
      }
      req.validatedQuery = { ...req.validatedQuery, sort };
    }

    next();
  } catch (error) {
    next(error);
  }
};

// Validate user input for creation/update
const validateUserInput = (req, res, next) => {
  try {
    const { name, email } = req.body;
    const errors = [];

    // Validate name
    if (!name || typeof name !== 'string') {
      errors.push('Name is required and must be a string');
    } else if (name.length < 2 || name.length > 50) {
      errors.push('Name must be between 2 and 50 characters');
    } else if (!/^[a-zA-Z\s'-]+$/.test(name)) {
      errors.push('Name contains invalid characters');
    }

    // Validate email
    if (!email || typeof email !== 'string') {
      errors.push('Email is required and must be a string');
    } else if (!validator.isEmail(email)) {
      errors.push('Invalid email format');
    } else if (email.length > 255) {
      errors.push('Email is too long');
    }

    if (errors.length > 0) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors
      });
    }

    // Sanitize inputs
    req.sanitizedBody = {
      name: validator.escape(name.trim()),
      email: validator.normalizeEmail(email.trim())
    };

    next();
  } catch (error) {
    next(error);
  }
};

// ===========================================
// ROUTES
// ===========================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Health check failed'
    });
  }
});

// Get all users with optional pagination
app.get('/users', validateQueryParams, (req, res, next) => {
  try {
    // Simulated user database (in production, use a real database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    // Apply pagination if provided
    const page = req.validatedQuery?.page || 1;
    const limit = req.validatedQuery?.limit || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    // Don't expose sensitive information
    const sanitizedUsers = paginatedUsers.map(({ id, name, email }) => ({
      id,
      name,
      email
    }));

    res.status(200).json({
      status: 'success',
      results: sanitizedUsers.length,
      total: users.length,
      page,
      totalPages: Math.ceil(users.length / limit),
      data: sanitizedUsers
    });
  } catch (error) {
    next(error);
  }
});

// Get user by ID
app.get('/users/:id', validateUserId, (req, res, next) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === req.validatedUserId);

    if (!user) {
      return res.status(404).json({
        status: 'error',
        message: 'User not found'
      });
    }

    // Don't expose sensitive information
    const { role, ...sanitizedUser } = user;

    res.status(200).json({
      status: 'success',
      data: sanitizedUser
    });
  } catch (error) {
    next(error);
  }
});

// Create new user (example POST endpoint)
app.post('/users', validateUserInput, (req, res, next) => {
  try {
    const { name, email } = req.sanitizedBody;

    // Simulated database operation
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name,
      email,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      status: 'success',
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

// ===========================================
// ERROR HANDLING
// ===========================================

// 404 handler - must be after all routes
app.use((req, res, next) => {
  res.status(404).json({
    status: 'error',
    message: `Cannot ${req.method} ${req.path}`,
    requestId: req.id // If you're using request ID middleware
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status: 'error',
      message: 'Validation error',
      errors: err.errors
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      status: 'error',
      message: 'Unauthorized access'
    });
  }

  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      status: 'error',
      message: 'Invalid token'
    });
  }

  if (err.type === 'entity.too.large') {
    return res.status(413).json({
      status: 'error',
      message: 'Request payload too large'
    });
  }

  // Generic error response
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    status: 'error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ===========================================
// SERVER
// ===========================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handler
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

// Graceful shutdown on SIGTERM
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

# Security Review & Improvement Recommendations for app.js

## Executive Summary
The original `app.js` lacks critical security measures and error handling. This document outlines vulnerabilities and provides actionable improvements.

---

## Critical Security Issues

### 1. **Input Validation** ⚠️ HIGH PRIORITY
**Problems:**
- No validation on route parameters
- No query parameter sanitization
- No request body validation
- Susceptible to injection attacks

**Solutions:**
- Implement validation middleware for all inputs
- Use validator libraries (e.g., `validator`, `joi`, `express-validator`)
- Whitelist allowed parameters
- Validate data types and formats

### 2. **Missing Security Headers** ⚠️ HIGH PRIORITY
**Problems:**
- No protection against XSS
- No clickjacking protection
- No MIME type sniffing prevention

**Solutions:**
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 3. **No Rate Limiting** ⚠️ HIGH PRIORITY
**Problems:**
- Vulnerable to DDoS attacks
- Vulnerable to brute force attacks
- No request throttling

**Solutions:**
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use('/api/', limiter);
```

### 4. **Error Handling** ⚠️ HIGH PRIORITY
**Problems:**
- No global error handler
- No try-catch blocks
- Errors could expose sensitive information
- No 404 handler

**Solutions:**
- Implement global error middleware
- Add try-catch in async routes
- Sanitize error messages in production
- Add 404 handler

### 5. **No Request Size Limits** ⚠️ MEDIUM PRIORITY
**Problems:**
- Vulnerable to large payload attacks
- Could cause memory exhaustion

**Solutions:**
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### 6. **CORS Configuration** ⚠️ MEDIUM PRIORITY
**Problems:**
- No CORS policy defined
- Could allow unauthorized cross-origin requests

**Solutions:**
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(','),
  credentials: true
}));
```

### 7. **NoSQL Injection Prevention** ⚠️ MEDIUM PRIORITY
**Problems:**
- No sanitization against NoSQL injection
- Vulnerable if using MongoDB or similar databases

**Solutions:**
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());
```

### 8. **XSS Prevention** ⚠️ MEDIUM PRIORITY
**Problems:**
- No XSS protection
- User input not sanitized

**Solutions:**
```javascript
const xss = require('xss-clean');
app.use(xss());
```

---

## Additional Security Best Practices

### 9. **Environment Variables**
**Current Issue:** Port hardcoded, no configuration management

**Recommendation:**
```javascript
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

### 10. **Logging & Monitoring**
**Current Issue:** No logging mechanism

**Recommendation:**
```javascript
const winston = require('winston');
const morgan = require('morgan');

app.use(morgan('combined'));
// Implement proper logging for errors and security events
```

### 11. **API Response Structure**
**Current Issue:** Inconsistent response format

**Recommendation:**
```javascript
// Standardized response format
{
  status: 'success' | 'error',
  message: 'string',
  data: {},
  errors: []
}
```

### 12. **Sensitive Data Exposure**
**Current Issue:** User data hardcoded in code

**Recommendation:**
- Move data to database
- Don't expose internal fields (role, password, etc.)
- Implement data access controls

### 13. **Process Management**
**Current Issue:** No graceful shutdown, no error process handlers

**Recommendation:**
```javascript
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION!');
  server.close(() => process.exit(1));
