// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const validator = require('validator'); // Input validation
const morgan = require('morgan'); // Logging

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers - Helmet protects against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Request logging for security monitoring
app.use(morgan('combined'));

// 3. Body parsing with size limits to prevent DoS
app.use(express.json({ 
  limit: '10kb', // Limit payload size
  strict: true // Only accept arrays and objects
}));

app.use(express.urlencoded({ 
  extended: false, 
  limit: '10kb' 
}));

// 4. Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.'
});

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Validate user ID parameter
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'User ID is required' 
    });
  }

  // Validate that ID is a positive integer
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId <= 0 || !Number.isInteger(numId)) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid user ID format. Must be a positive integer.' 
    });
  }

  // Check for SQL injection patterns (even if not using SQL)
  if (!/^\d+$/.test(id)) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid user ID format.' 
    });
  }

  req.validatedId = numId;
  next();
};

// Validate query parameters
const validateQueryParams = (req, res, next) => {
  const { limit, offset, search } = req.query;

  // Validate limit
  if (limit !== undefined) {
    const numLimit = parseInt(limit, 10);
    if (isNaN(numLimit) || numLimit < 1 || numLimit > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Limit must be between 1 and 100'
      });
    }
    req.validatedQuery = { ...req.validatedQuery, limit: numLimit };
  }

  // Validate offset
  if (offset !== undefined) {
    const numOffset = parseInt(offset, 10);
    if (isNaN(numOffset) || numOffset < 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Offset must be a non-negative integer'
      });
    }
    req.validatedQuery = { ...req.validatedQuery, offset: numOffset };
  }

  // Sanitize search parameter
  if (search !== undefined) {
    if (typeof search !== 'string' || search.length > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Search term must be a string with max 100 characters'
      });
    }
    // Remove potentially dangerous characters
    const sanitizedSearch = validator.escape(search.trim());
    req.validatedQuery = { ...req.validatedQuery, search: sanitizedSearch };
  }

  next();
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Even simple endpoints should have error handling
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'An unexpected error occurred' 
    });
  }
});

// Get all users endpoint with validation
app.get('/api/users', validateQueryParams, (req, res) => {
  try {
    // In production, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if provided
    const limit = req.validatedQuery?.limit || 10;
    const offset = req.validatedQuery?.offset || 0;

    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      metadata: {
        total: users.length,
        limit,
        offset
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to fetch users' 
    });
  }
});

// Get single user by ID with validation
app.get('/api/users/:id', strictLimiter, validateUserId, (req, res) => {
  try {
    const userId = req.validatedId;

    // In production, query database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not Found',
        message: 'User not found' 
      });
    }

    res.json({ data: user });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to fetch user' 
    });
  }
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource does not exist' 
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for monitoring
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.status === 404 ? 'Not Found' : 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// SERVER INITIALIZATION
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Graceful shutdown handler
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

# Security Review: app.js

## Executive Summary

The original `app.js` file has several critical security vulnerabilities that could lead to:
- Denial of Service (DoS) attacks
- Information disclosure
- Cross-Site Scripting (XSS)
- Injection attacks
- Brute force attacks

## Critical Issues Found

### 1. **No Input Validation** 🔴 CRITICAL
**Issue**: The application accepts any input without validation.

**Risk**: 
- SQL/NoSQL injection attacks
- Command injection
- Path traversal
- Buffer overflow

**Solution**:
```javascript
// Validate all user inputs
const validateUserId = (req, res, next) => {
  const { id } = req.params;
  const numId = parseInt(id, 10);

  if (isNaN(numId) || numId <= 0) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  req.validatedId = numId;
  next();
};
```

### 2. **No Error Handling** 🔴 CRITICAL
**Issue**: Unhandled errors can crash the application and leak sensitive information.

**Risk**:
- Application crashes
- Stack trace exposure
- Sensitive data leakage

**Solution**:
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred'
  });
});
```

### 3. **Missing Security Headers** 🔴 CRITICAL
**Issue**: No protection against common web vulnerabilities.

**Risk**:
- XSS attacks
- Clickjacking
- MIME-type sniffing
- Man-in-the-middle attacks

**Solution**:
```javascript
const helmet = require('helmet');
app.use(helmet());
```

### 4. **No Rate Limiting** 🟡 HIGH
**Issue**: API endpoints can be abused with unlimited requests.

**Risk**:
- Brute force attacks
- DoS attacks
- Resource exhaustion
- Credential stuffing

**Solution**:
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use('/api/', limiter);
```

### 5. **No Request Size Limits** 🟡 HIGH
**Issue**: Application accepts unlimited request body sizes.

**Risk**:
- DoS through large payloads
- Memory exhaustion
- Server crash

**Solution**:
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));
```

### 6. **Information Disclosure** 🟡 MEDIUM
**Issue**: Error messages and responses may leak sensitive information.

**Risk**:
- Exposes internal structure
- Reveals technology stack
- Helps attackers map the system

**Solution**:
```javascript
// Don't expose stack traces in production
if (process.env.NODE_ENV !== 'development') {
  delete err.stack;
}
```

### 7. **No Logging/Monitoring** 🟡 MEDIUM
**Issue**: No audit trail for security events.

**Risk**:
- Can't detect attacks
- No forensic evidence
- Compliance violations

**Solution**:
```javascript
const morgan = require('morgan');
app.use(morgan('combined'));
```

### 8. **No CORS Configuration** 🟢 LOW
**Issue**: CORS not configured, could be too permissive or too restrictive.

**Solution**:
```javascript
const cors = require('cors');

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  optionsSuccessStatus: 200,
  credentials: true
};

app.use(cors(corsOptions));
```

### 9. **No Authentication/Authorization** 🟡 HIGH
**Issue**: All endpoints are publicly accessible.

**Risk**:
- Unauthorized data access
- Data manipulation
- Privacy violations

**Solution**:
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Verify token (using JWT or similar)
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

app.use('/api/', authenticateToken);
```

## Additional Security Best Practices

### 10. **Environment Variables**
Store sensitive configuration in environment variables:

```javascript
// .env file
PORT=3000
NODE_ENV=production
JWT_SECRET=your-secret-key-here
DB_CONNECTION_STRING=your-db-connection
ALLOWED_ORIGINS=https://example.com,https://app.example.com
```

### 11. **HTTPS Only**
Enforce HTTPS in production:

```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}
```

### 12. **Sanitize User Input**
Always sanitize and escape user input:

```javascript
const validator = require('validator');

const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return validator.escape(input.trim());
  }
  return input;
};
```

### 13. **Secure Dependencies**
Regularly audit and update dependencies:

```bash
npm audit
npm audit fix
npm outdated
```

### 14. **Content Security Policy**
Implement strict CSP:

```javascript
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"]
  }
}));
```

## Required Dependencies

Add these to your `package.json`:

```bash
npm install helmet express-rate-limit validator morgan cors
npm install --save-dev dotenv
```

## Implementation Priority

1. **IMMEDIATE** (Deploy within 24 hours):
   - Add error handling middleware
   - Implement input validation
   - Add helmet for security headers
   - Set request size limits

2. **HIGH** (Deploy within 1 week):
   - Implement rate limiting
   - Add logging/monitoring
   - Add authentication/authorization
   - Configure CORS properly

3. **MEDIUM** (Deploy within 1 month):
   - Implement comprehensive audit logging
   - Add security testing (penetration testing)
