// SECURITY MIDDLEWARE
// ============================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Request logging
app.use(morgan('combined'));

// Body parsing with size limits
app.use(express.json({ limit: '10kb', strict: true }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'User ID is required' 
    });
  }

  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId <= 0 || !Number.isInteger(numId)) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid user ID format. Must be a positive integer.' 
    });
  }

  if (!/^\d+$/.test(id)) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid user ID format.' 
    });
  }

  req.validatedId = numId;
  next();
};

const validateQueryParams = (req, res, next) => {
  const { limit, offset, search } = req.query;

  if (limit !== undefined) {
    const numLimit = parseInt(limit, 10);
    if (isNaN(numLimit) || numLimit < 1 || numLimit > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Limit must be between 1 and 100'
      });
    }
    req.validatedQuery = { ...req.validatedQuery, limit: numLimit };
  }

  if (offset !== undefined) {
    const numOffset = parseInt(offset, 10);
    if (isNaN(numOffset) || numOffset < 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Offset must be a non-negative integer'
      });
    }
    req.validatedQuery = { ...req.validatedQuery, offset: numOffset };
  }

  if (search !== undefined) {
    if (typeof search !== 'string' || search.length > 100) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Search term must be a string with max 100 characters'
      });
    }
    const sanitizedSearch = validator.escape(search.trim());
    req.validatedQuery = { ...req.validatedQuery, search: sanitizedSearch };
  }

  next();
};

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'An unexpected error occurred' 
    });
  }
});

app.get('/api/users', validateQueryParams, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const limit = req.validatedQuery?.limit || 10;
    const offset = req.validatedQuery?.offset || 0;

    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      metadata: {
        total: users.length,
        limit,
        offset
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to fetch users' 
    });
  }
});

app.get('/api/users/:id', validateUserId, (req, res) => {
  try {
    const userId = req.validatedId;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not Found',
        message: 'User not found' 
      });
    }

    res.json({ data: user });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Unable to fetch user' 
    });
  }
});

// ============================================
// ERROR HANDLING
// ============================================

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: 'The requested resource does not exist' 
  });
});

app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.status === 404 ? 'Not Found' : 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// SERVER INITIALIZATION
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
```

