// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // npm install helmet
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const validator = require('validator'); // npm install validator
const mongoSanitize = require('express-mongo-sanitize'); // npm install express-mongo-sanitize
const xss = require('xss-clean'); // npm install xss-clean

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate limiting to prevent brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// 3. Body parser with size limits to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 5. Data sanitization against XSS
app.use(xss());

// 6. Prevent parameter pollution
app.use((req, res, next) => {
  // Remove duplicate query parameters
  for (let key in req.query) {
    if (Array.isArray(req.query[key])) {
      req.query[key] = req.query[key][0];
    }
  }
  next();
});

// 7. Disable X-Powered-By header
app.disable('x-powered-by');

// ============================================
// REQUEST LOGGING (Security Events)
// ============================================
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

/**
 * Validates and sanitizes user ID parameter
 * @param {string} id - User ID to validate
 * @returns {Object} - { valid: boolean, sanitized: number|null, error: string|null }
 */
const validateUserId = (id) => {
  if (!id) {
    return { valid: false, sanitized: null, error: 'User ID is required' };
  }

  // Check if it's a valid integer
  if (!validator.isInt(String(id), { min: 1, max: 999999 })) {
    return { valid: false, sanitized: null, error: 'Invalid user ID format' };
  }

  const sanitizedId = parseInt(id, 10);
  return { valid: true, sanitized: sanitizedId, error: null };
};

/**
 * Validates email format
 * @param {string} email - Email to validate
 * @returns {boolean}
 */
const validateEmail = (email) => {
  return validator.isEmail(email);
};

/**
 * Sanitizes string input to prevent XSS
 * @param {string} input - String to sanitize
 * @returns {string}
 */
const sanitizeString = (input) => {
  if (typeof input !== 'string') return '';
  return validator.escape(input.trim());
};

// ============================================
// ROUTES WITH PROPER ERROR HANDLING
// ============================================

/**
 * Health check endpoint
 * GET /health
 */
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Even simple endpoints should have error handling
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error',
      message: 'Internal server error' 
    });
  }
});

/**
 * Get all users endpoint with pagination and validation
 * GET /users?page=1&limit=10
 */
app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    let page = 1;
    let limit = 10;

    if (req.query.page) {
      if (!validator.isInt(String(req.query.page), { min: 1, max: 1000 })) {
        return res.status(400).json({
          error: 'Invalid page parameter',
          message: 'Page must be a positive integer between 1 and 1000'
        });
      }
      page = parseInt(req.query.page, 10);
    }

    if (req.query.limit) {
      if (!validator.isInt(String(req.query.limit), { min: 1, max: 100 })) {
        return res.status(400).json({
          error: 'Invalid limit parameter',
          message: 'Limit must be a positive integer between 1 and 100'
        });
      }
      limit = parseInt(req.query.limit, 10);
    }

    // In production, this would query a database with proper parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length
      }
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

/**
 * Get user by ID with validation
 * GET /users/:id
 */
app.get('/users/:id', (req, res, next) => {
  try {
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({
        error: 'Validation error',
        message: validation.error
      });
    }

    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === validation.sanitized);

    if (!user) {
      return res.status(404).json({
        error: 'Not found',
        message: 'User not found'
      });
    }

    res.status(200).json({
      success: true,
      data: user
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Create user endpoint with comprehensive validation
 * POST /users
 */
app.post('/users', async (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Name and email are required'
      });
    }

    // Validate name length and format
    if (typeof name !== 'string' || name.trim().length < 2 || name.trim().length > 100) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Name must be between 2 and 100 characters'
      });
    }

    // Validate email format
    if (!validateEmail(email)) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Invalid email format'
      });
    }

    // Sanitize inputs
    const sanitizedName = sanitizeString(name);
    const sanitizedEmail = validator.normalizeEmail(email);

    // In production, save to database with parameterized queries
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name: sanitizedName,
      email: sanitizedEmail
    };

    console.log('User created:', { id: newUser.id, name: sanitizedName });

    res.status(201).json({
      success: true,
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// 404 HANDLER
// ============================================
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource does not exist'
  });
});

// ============================================
// GLOBAL ERROR HANDLING MIDDLEWARE
// ============================================
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error('Error occurred:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An internal error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: 'Server error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================
// GRACEFUL SHUTDOWN HANDLING
// ============================================
let server;

const startServer = (port = 3000) => {
  server = app.listen(port, () => {
    console.log(`Server running securely on port ${port}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    // In production, log to monitoring service and gracefully shutdown
    gracefulShutdown('UNHANDLED_REJECTION');
  });

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    gracefulShutdown('UNCAUGHT_EXCEPTION');
  });

  // Handle SIGTERM
  process.on('SIGTERM', () => {
    console.log('SIGTERM received');
    gracefulShutdown('SIGTERM');
  });

  // Handle SIGINT (Ctrl+C)
  process.on('SIGINT', () => {
    console.log('SIGINT received');
    gracefulShutdown('SIGINT');
  });
};

const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  if (server) {
    server.close(() => {
      console.log('Server closed. Process terminating...');
      process.exit(signal === 'UNCAUGHT_EXCEPTION' ? 1 : 0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  } else {
    process.exit(signal === 'UNCAUGHT_EXCEPTION' ? 1 : 0);
  }
};

// Start server if running directly
if (require.main === module) {
  startServer();
}

module.exports = app;

# Security Review: app.js

## Executive Summary

The current `app.js` implementation has **critical security vulnerabilities** that could lead to:
- Denial of Service (DoS) attacks
- Cross-Site Scripting (XSS)
- Injection attacks
- Information disclosure
- Server crashes from unhandled errors

## Critical Issues Found

### 1. **No Input Validation** 🔴 HIGH RISK
**Current State:** No validation of any user inputs
**Risk:** Injection attacks, application crashes, unexpected behavior
**Fix:** Implement comprehensive validation for all inputs

### 2. **Missing Security Headers** 🔴 HIGH RISK
**Current State:** No security headers (HSTS, CSP, X-Frame-Options, etc.)
**Risk:** XSS, clickjacking, MIME-sniffing attacks
**Fix:** Use `helmet` middleware

### 3. **No Rate Limiting** 🔴 HIGH RISK
**Current State:** Unlimited requests allowed
**Risk:** DoS attacks, brute force attacks, resource exhaustion
**Fix:** Implement `express-rate-limit`

### 4. **No Error Handling** 🟡 MEDIUM RISK
**Current State:** No try-catch blocks or error middleware
**Risk:** Information disclosure, server crashes, poor user experience
**Fix:** Implement global error handler and try-catch in routes

### 5. **No Request Body Parsing Configuration** 🟡 MEDIUM RISK
**Current State:** No body parser configured
**Risk:** Cannot process POST/PUT requests safely
**Fix:** Configure body parser with size limits

### 6. **No Logging** 🟡 MEDIUM RISK
**Current State:** Only startup console.log
**Risk:** Cannot track security incidents or debug issues
**Fix:** Implement request logging and error logging

### 7. **Information Disclosure** 🟡 MEDIUM RISK
**Current State:** X-Powered-By header enabled
**Risk:** Reveals server technology, aids attackers
**Fix:** Disable with `app.disable('x-powered-by')`

## Detailed Recommendations

### Security Headers (Use Helmet)
```javascript
const helmet = require('helmet');
app.use(helmet({
  contentSecurityPolicy: true,
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true
  }
}));
```

### Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP
});
app.use('/api/', limiter);
```

### Input Validation
```javascript
const validator = require('validator');

// Validate user ID
if (!validator.isInt(String(id), { min: 1 })) {
  return res.status(400).json({ error: 'Invalid ID' });
}

// Validate email
if (!validator.isEmail(email)) {
  return res.status(400).json({ error: 'Invalid email' });
}
```

### Error Handling
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;
  res.status(statusCode).json({ error: message });
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  // Log and gracefully shutdown
});
```

### Body Parser Configuration
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

### XSS Protection
```javascript
const xss = require('xss-clean');
app.use(xss());

// Also sanitize all string inputs
const sanitized = validator.escape(userInput.trim());
```

### NoSQL Injection Prevention
```javascript
const mongoSanitize = require('express-mongo-sanitize');
app.use(mongoSanitize());
```

## Additional Best Practices

### 1. Environment Variables
```javascript
// Use dotenv for configuration
require('dotenv').config();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
```

### 2. CORS Configuration
```javascript
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS.split(','),
  credentials: true,
  optionsSuccessStatus: 200
}));
```

### 3. Request Size Limits
Already covered in body parser, but also consider:
```javascript
// Limit URL query string size
app.use((req, res, next) => {
  if (req.url.length > 2048) {
    return res.status(414).json({ error: 'URI too long' });
  }
  next();
});
```

### 4. Secure Session Management (if using sessions)
```javascript
const session = require('express-session');
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
