// Secure Express Application with Best Practices
// Enhanced version with error handling, validation, and security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet - Sets secure HTTP headers
app.use(helmet());

// 2. Rate Limiting - Prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: 'Too many requests, please try again later.',
});

// 3. Body parsing with size limits
app.use(express.json({ 
  limit: '10kb',
  strict: true 
}));
app.use(express.urlencoded({ 
  extended: false, 
  limit: '10kb' 
}));

// 4. CORS Configuration (adjust as needed)
app.use((req, res, next) => {
  // Only allow specific origins in production
  const allowedOrigins = process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',')
    : ['http://localhost:3000'];

  const origin = req.headers.origin;
  if (allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.setHeader('Access-Control-Allow-Credentials', 'true');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }
  next();
});

// 5. Disable X-Powered-By header
app.disable('x-powered-by');

// ============================================
// REQUEST LOGGING (for monitoring)
// ============================================
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    }));
  });
  next();
});

// ============================================
// INPUT VALIDATION HELPERS
// ============================================

const validateUserId = (id) => {
  if (!id) return { valid: false, error: 'User ID is required' };

  // Ensure it's a positive integer
  const numId = parseInt(id, 10);
  if (isNaN(numId) || numId < 1 || numId > 1000000) {
    return { valid: false, error: 'Invalid user ID format' };
  }

  return { valid: true, value: numId };
};

const validateEmail = (email) => {
  if (!email) return { valid: false, error: 'Email is required' };

  if (!validator.isEmail(email)) {
    return { valid: false, error: 'Invalid email format' };
  }

  // Additional sanitization
  const sanitized = validator.normalizeEmail(email);
  return { valid: true, value: sanitized };
};

const validateSearchQuery = (query) => {
  if (!query) return { valid: true, value: '' };

  // Limit length to prevent DoS
  if (query.length > 100) {
    return { valid: false, error: 'Search query too long (max 100 characters)' };
  }

  // Sanitize to prevent injection
  const sanitized = validator.escape(query.trim());
  return { valid: true, value: sanitized };
};

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(200).json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Get all users endpoint with optional filtering
app.get('/users', (req, res, next) => {
  try {
    // Mock data - in production, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Input validation for query parameters
    if (req.query.search) {
      const searchValidation = validateSearchQuery(req.query.search);
      if (!searchValidation.valid) {
        return res.status(400).json({
          error: 'Validation Error',
          message: searchValidation.error
        });
      }

      // Filter users based on sanitized search query
      const searchTerm = searchValidation.value.toLowerCase();
      const filtered = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );

      return res.status(200).json({
        data: filtered,
        count: filtered.length
      });
    }

    // Return all users
    res.status(200).json({
      data: users,
      count: users.length
    });

  } catch (error) {
    next(error);
  }
});

// Get user by ID endpoint
app.get('/users/:id', (req, res, next) => {
  try {
    const validation = validateUserId(req.params.id);

    if (!validation.valid) {
      return res.status(400).json({
        error: 'Validation Error',
        message: validation.error
      });
    }

    // Mock data - in production, query database with validated ID
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === validation.value);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: 'User not found'
      });
    }

    res.status(200).json({ data: user });

  } catch (error) {
    next(error);
  }
});

// Example POST endpoint with validation
app.post('/users', strictLimiter, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Name and email are required'
      });
    }

    // Validate name
    if (typeof name !== 'string' || name.trim().length < 2 || name.length > 100) {
      return res.status(400).json({
        error: 'Validation Error',
        message: 'Name must be between 2 and 100 characters'
      });
    }

    // Validate email
    const emailValidation = validateEmail(email);
    if (!emailValidation.valid) {
      return res.status(400).json({
        error: 'Validation Error',
        message: emailValidation.error
      });
    }

    // Sanitize name
    const sanitizedName = validator.escape(name.trim());

    // In production, save to database with parameterized queries
    const newUser = {
      id: 3, // Would be auto-generated by database
      name: sanitizedName,
      email: emailValidation.value
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });

  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 Handler - Must come after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// Global Error Handler - Must be last
app.use((err, req, res, next) => {
  // Log error details for debugging (use proper logging service in production)
  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  }));

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      message: isDevelopment ? err.message : 'Invalid input data'
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  // Handle JSON parsing errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON payload'
    });
  }

  // Default error response
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handler
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running securely on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

