// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');
const morgan = require('morgan');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet - Sets various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Rate Limiting - Prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3. Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Request logging (use appropriate logging library in production)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

/**
 * Validates user ID parameter
 */
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID is required'
    });
  }

  // Validate that ID is a positive integer
  if (!validator.isInt(id, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID must be a positive integer'
    });
  }

  next();
};

/**
 * Validates query parameters
 */
const validateQueryParams = (req, res, next) => {
  const { page, limit, sort } = req.query;

  // Validate page number
  if (page && !validator.isInt(page, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Page must be a positive integer'
    });
  }

  // Validate limit
  if (limit && !validator.isInt(limit, { min: 1, max: 100 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Limit must be between 1 and 100'
    });
  }

  // Validate sort (whitelist approach)
  if (sort && !['name', 'id', 'email'].includes(sort)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid sort parameter. Allowed values: name, id, email'
    });
  }

  next();
};

/**
 * Sanitizes string inputs to prevent XSS
 */
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return validator.escape(input);
  }
  return input;
};

