## 8. Mass Assignment

### Attack Example
```bash
# Attacker tries to set admin field
curl -X POST http://localhost:3000/users \
  -H "Content-Type: application/json" \
  -d '{
    "name": "Attacker",
    "email": "attacker@evil.com",
    "isAdmin": true,
    "role": "admin"
  }'
```

### Protection in Improved Code
```javascript
// Whitelist allowed fields
app.post('/users', (req, res) => {
  const { name, email } = req.body;

  // Only use explicitly allowed fields
  const newUser = {
    name: sanitizeInput(name),
    email: validator.normalizeEmail(email),
    // isAdmin and role are NOT assigned from request
    isAdmin: false,
    role: 'user',
    createdAt: new Date()
  };

  // Save newUser...
});
```

**Additional Protection (Recommended)**:
```javascript
// Use express-validator with field whitelisting
const { body, validationResult } = require('express-validator');

app.post('/users', [
  body('name').isString().trim().isLength({ min: 2, max: 50 }),
  body('email').isEmail().normalizeEmail(),
  // Only these fields are validated - others are ignored
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Continue with validated data only
});
```

