## 10. CSRF (Cross-Site Request Forgery)

### Attack Example
```html
<!-- Attacker's malicious page -->
<form action="http://yourapp.com/users/delete" method="POST">
  <input type="hidden" name="id" value="123">
</form>
<script>
  document.forms[0].submit();
</script>
```

### Protection (Recommended)
```javascript
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: true }));

// Send CSRF token to client
app.get('/form', (req, res) => {
  res.render('form', { csrfToken: req.csrfToken() });
});

// Validate CSRF token on POST
app.post('/users', (req, res) => {
  // csurf middleware automatically validates token
  // Requests without valid token are rejected
});

// SameSite cookie attribute (from improved code)
app.use(session({
  cookie: {
    sameSite: 'strict', // Prevents CSRF
    httpOnly: true,
    secure: true
  }
}));
```

