// Secure Express Application with Best Practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Security Headers (helmet)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime
    });
  }
});
app.use(limiter);

// 4. Body Parser with size limits
app.use(express.json({ 
  limit: '10kb',
  strict: true 
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 5. Request Logging (use winston in production)
app.use(morgan('combined'));

// 6. Disable x-powered-by header
app.disable('x-powered-by');

// ===== VALIDATION MIDDLEWARE =====

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg
      }))
    });
  }
  next();
};

// ===== ROUTES =====

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// Get users endpoint with query validation
app.get('/users', [
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .withMessage('Page must be an integer between 1 and 1000'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be an integer between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .escape()
    .isLength({ max: 100 })
    .withMessage('Search term too long'),
  handleValidationErrors
], (req, res) => {
  try {
    // In production, fetch from database with parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const search = req.query.search;

    let filteredUsers = users;

    // Safe search filtering
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower)
      );
    }

    res.status(200).json({
      data: filteredUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length
      }
    });
  } catch (error) {
    // Log error securely (don't expose to client)
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to fetch users'
    });
  }
});

// Get single user by ID with validation
app.get('/users/:id', [
  query('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  handleValidationErrors
], (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    // Validate ID is a number
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({ 
        error: 'Invalid user ID',
        message: 'User ID must be a positive integer'
      });
    }

    // Mock database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ 
        error: 'Not found',
        message: 'User not found'
      });
    }

    res.status(200).json({ data: user });
  } catch (error) {
    console.error('Error in /users/:id endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to fetch user'
    });
  }
});

// Create user with validation
app.post('/users', [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 255 }).withMessage('Email too long'),
  handleValidationErrors
], (req, res) => {
  try {
    const { name, email } = req.body;

    // In production: Check for duplicate email in database
    // Use parameterized queries to prevent SQL injection

    const newUser = {
      id: Date.now(), // In production, use database-generated ID
      name,
      email,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({ 
      message: 'User created successfully',
      data: newUser 
    });
  } catch (error) {
    console.error('Error in POST /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to create user'
    });
  }
});

// ===== ERROR HANDLING =====

// 404 Handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    message: 'The requested resource was not found'
  });
});

// Global Error Handler
app.use((err, req, res, next) => {
  // Log error securely
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal errors to client
  const statusCode = err.statusCode || 500;
  const message = err.isOperational 
    ? err.message 
    : 'An unexpected error occurred';

  res.status(statusCode).json({
    error: 'Internal server error',
    message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

