// Improved application with security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS configuration
const morgan = require('morgan'); // Logging
const validator = require('validator'); // Input validation

const app = express();

// =====================
// SECURITY MIDDLEWARE
// =====================

// Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Enable CORS with restrictions
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts, please try again later.',
});

// Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging (don't log sensitive data)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined', {
    skip: (req, res) => res.statusCode < 400, // Only log errors in production
    stream: {
      write: (message) => {
        // In production, use proper logging service (Winston, Bunyan, etc.)
        console.log(message.trim());
      }
    }
  }));
}

// Request timeout
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  res.setTimeout(30000);
  next();
});

// =====================
// INPUT VALIDATION
// =====================

// Validation middleware for user ID
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (!id) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'User ID is required'
    });
  }

  // Validate ID is a positive integer
  if (!validator.isInt(id, { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid user ID format. Must be a positive integer.'
    });
  }

  next();
};

// Validation middleware for query parameters
const validateQueryParams = (req, res, next) => {
  const { page, limit, search } = req.query;

  // Validate pagination
  if (page && !validator.isInt(String(page), { min: 1 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid page number'
    });
  }

  if (limit && !validator.isInt(String(limit), { min: 1, max: 100 })) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid limit. Must be between 1 and 100.'
    });
  }

  // Sanitize search parameter to prevent injection
  if (search && search.length > 100) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Search query too long'
    });
  }

  // Check for suspicious patterns (basic XSS/injection prevention)
  if (search && /<script|javascript:|onerror=|onclick=/i.test(search)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid search query'
    });
  }

  next();
};

// Sanitize output to prevent XSS
const sanitizeOutput = (data) => {
  if (typeof data === 'string') {
    return validator.escape(data);
  }
  if (Array.isArray(data)) {
    return data.map(sanitizeOutput);
  }
  if (typeof data === 'object' && data !== null) {
    const sanitized = {};
    for (const [key, value] of Object.entries(data)) {
      sanitized[key] = sanitizeOutput(value);
    }
    return sanitized;
  }
  return data;
};

// =====================
// ROUTES
// =====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    // Don't expose internal errors
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Health check failed'
    });
  }
});

// Get all users with validation
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { page = 1, limit = 10, search = '' } = req.query;

    // Mock data - in production, this would query a database
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided
    if (search) {
      const searchLower = search.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const startIndex = (parseInt(page) - 1) * parseInt(limit);
    const endIndex = startIndex + parseInt(limit);
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Sanitize output to prevent XSS
    const sanitizedUsers = sanitizeOutput(paginatedUsers);

    res.json({
      data: sanitizedUsers,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length,
        totalPages: Math.ceil(users.length / parseInt(limit))
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to retrieve users'
    });
  }
});

// Get single user by ID with validation
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const userId = parseInt(req.params.id);

    // Mock data - in production, this would query a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `User with ID ${userId} not found`
      });
    }

    // Sanitize output
    const sanitizedUser = sanitizeOutput(user);

    res.json({ data: sanitizedUser });
  } catch (error) {
    console.error('Error fetching user:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Failed to retrieve user'
    });
  }
});

// =====================
// ERROR HANDLING
// =====================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error('Unhandled error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't expose internal error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'An unexpected error occurred'
    : err.message;

  res.status(statusCode).json({
    error: 'Internal Server Error',
    message: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// =====================
// SERVER CONFIGURATION
// =====================

// Use environment variable for port
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, log to monitoring service before exiting
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, log to monitoring service
});

module.exports = app;

