#!/usr/bin/env node
// check-env.js - Utility to audit environment variable usage

const fs = require('fs');
const path = require('path');

console.log('🔍 Environment Variables Audit\n');
console.log('=' .repeat(60));

function findEnvVars(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const regex = /process\.env\.([A-Z_][A-Z0-9_]*)/g;
  const matches = [...content.matchAll(regex)];
  return [...new Set(matches.map(m => m[1]))];
}

function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) return {};

  const content = fs.readFileSync(filePath, 'utf8');
  const vars = {};

  content.split('\n').forEach(line => {
    line = line.trim();
    if (!line || line.startsWith('#')) return;

    const [key, ...valueParts] = line.split('=');
    if (key) {
      vars[key.trim()] = valueParts.join('=').trim();
    }
  });

  return vars;
}

// Check JavaScript files
console.log('\n📄 JavaScript Files:\n');
const jsFiles = ['app.js', 'app.secure.js', 'app.test.js'];

const usedVars = new Set();

jsFiles.forEach(file => {
  if (fs.existsSync(file)) {
    const vars = findEnvVars(file);
    console.log(`   ${file}:`);
    if (vars.length === 0) {
      console.log(`      ❌ No environment variables used`);
    } else {
      vars.forEach(v => {
        console.log(`      ✅ process.env.${v}`);
        usedVars.add(v);
      });
    }
  }
});

// Check .env files
console.log('\n' + '='.repeat(60));
console.log('\n📋 Environment Files:\n');

const envFiles = ['.env', '.env.test', '.env.example', '.env.local', '.env.development', '.env.production'];

const definedVars = new Map();

envFiles.forEach(file => {
  if (fs.existsSync(file)) {
    const vars = parseEnvFile(file);
    const keys = Object.keys(vars);

    console.log(`   ${file}:`);
    if (keys.length === 0) {
      console.log(`      (empty)`);
    } else {
      keys.forEach(key => {
        const value = vars[key];
        const isCanary = value.includes('CANARY');
        const isSensitive = key.includes('SECRET') || key.includes('KEY') || key.includes('PASSWORD') || key.includes('TOKEN');

        let icon = '📋';
        if (isCanary) icon = '🐤';
        else if (isSensitive) icon = '🔐';

        console.log(`      ${icon} ${key}${isCanary ? ' (CANARY)' : ''}`);

        if (!definedVars.has(key)) {
          definedVars.set(key, []);
        }
        definedVars.get(key).push(file);
      });
    }
    console.log('');
  }
});

// Analysis
console.log('='.repeat(60));
console.log('\n📊 Analysis:\n');

console.log(`   Environment variables USED in code: ${usedVars.size}`);
console.log(`   Environment variables DEFINED in files: ${definedVars.size}`);

// Check for unused variables
const unusedVars = [...definedVars.keys()].filter(v => !usedVars.has(v));
if (unusedVars.length > 0) {
  console.log(`\n   ⚠️  Variables defined but NOT used in code: ${unusedVars.length}`);
  unusedVars.forEach(v => {
    console.log(`      - ${v} (in ${definedVars.get(v).join(', ')})`);
  });
}

// Check for undefined variables
const undefinedVars = [...usedVars].filter(v => !definedVars.has(v));
if (undefinedVars.length > 0) {
  console.log(`\n   ⚠️  Variables used but NOT defined: ${undefinedVars.length}`);
  undefinedVars.forEach(v => {
    console.log(`      - ${v} (will use system environment or undefined)`);
  });
}

// Security check
console.log('\n' + '='.repeat(60));
console.log('\n🔒 Security Check:\n');

let hasIssues = false;

// Check for canary tokens
const canaryVars = [...definedVars.entries()].filter(([key, files]) => {
  return files.some(f => {
    const vars = parseEnvFile(f);
    return vars[key] && vars[key].includes('CANARY');
  });
});

if (canaryVars.length > 0) {
  console.log(`   🐤 Canary tokens detected: ${canaryVars.length}`);
  canaryVars.forEach(([key, files]) => {
    const isUsed = usedVars.has(key);
    console.log(`      - ${key} in ${files.join(', ')} ${isUsed ? '⚠️ USED' : '✅ unused'}`);
  });
  hasIssues = canaryVars.some(([key]) => usedVars.has(key));
}

// Check for .env in git
if (fs.existsSync('.gitignore')) {
  const gitignore = fs.readFileSync('.gitignore', 'utf8');
  const ignoresEnv = gitignore.includes('.env');

  if (ignoresEnv) {
    console.log(`\n   ✅ .env files are gitignored`);
  } else {
    console.log(`\n   ❌ WARNING: .env files may not be gitignored!`);
    hasIssues = true;
  }
}

// Check for sensitive values in non-test files
['.env', '.env.local', '.env.development'].forEach(file => {
  if (fs.existsSync(file)) {
    const vars = parseEnvFile(file);
    const sensitive = Object.entries(vars).filter(([k, v]) => 
      k.includes('SECRET') || k.includes('PASSWORD') || k.includes('KEY') || k.includes('TOKEN')
    );

    if (sensitive.length > 0) {
      console.log(`\n   ⚠️  Sensitive values in ${file}: ${sensitive.length}`);
      console.log(`      Make sure this file is NOT committed to git!`);
      hasIssues = true;
    }
  }
});

console.log('\n' + '='.repeat(60));

if (!hasIssues && usedVars.size > 0) {
  console.log('\n✅ No security issues detected!\n');
} else if (usedVars.size === 0) {
  console.log('\nℹ️  Application does not use environment variables.\n');
} else {
  console.log('\n⚠️  Please review the warnings above.\n');
}
